"""The corpus seam: where indexable documents come from.

A ``BaseCorpusSource`` yields the documents to index plus an opaque
``corpus_version`` identifying the snapshot. Any data source — the docs repo
today, skills/tools/history later — implements this one interface, so ingestion
and indexing never depend on a specific source format.
"""

from abc import ABC, abstractmethod
from pathlib import Path
from typing import List, Tuple

from rasa.builder.document_retrieval.source import SourceDocument


class BaseCorpusSource(ABC):
    """A source of documents to index, with a snapshot version."""

    @abstractmethod
    def load(self) -> Tuple[List[SourceDocument], str]:
        """Load the corpus.

        Returns:
            A tuple ``(documents, corpus_version)`` where ``corpus_version`` is an
            opaque string identifying this snapshot (e.g. a git commit). Used to
            stamp the index and drive incremental sync.
        """
        ...


class DocsRepoSource(BaseCorpusSource):
    """Yields Rasa documentation pages from a prebuilt docs index file.

    Adapts each page into the canonical ``SourceDocument`` and uses the docs-repo
    commit as the corpus version.
    """

    def __init__(self, docs_index_path: str) -> None:
        self._docs_index_path = docs_index_path

    def load(self) -> Tuple[List[SourceDocument], str]:
        # Lazy import: the docs-index loader is builder-side; keep it out of this
        # module's import path.
        from rasa.builder.evaluator.dataset.data_gen.retrieval.docs_index import (
            DocIndex,
        )

        doc_index = DocIndex.load_from_jsonl(Path(self._docs_index_path))
        documents = [page.to_source_document() for page in doc_index.pages]
        return documents, doc_index.docs_repo_commit
